export async function gate({ referenceDir, submissionDir }) {
  const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');
  let pinnedSrc;
  try {
    pinnedSrc = readFileSync(pinnedPath, 'utf8');
  } catch (e) {
    return { accept: false, reason: 'Could not read pinned test cases: ' + e.message };
  }

  const answerPath = path.join(submissionDir, 'answer.mjs');
  if (!existsSync(answerPath)) {
    return { accept: false, reason: 'answer.mjs not found in submission.' };
  }

  const answerUrl = pathToFileURL(answerPath).href;

  const expectedTestCount = (pinnedSrc.match(/\btest\s*\(/g) || []).length;
  if (expectedTestCount === 0) {
    return { accept: false, reason: 'Could not find any test cases in pinned test file.' };
  }

  const runnerSrc =
    "import test from 'node:test';\n" +
    "import assert from 'node:assert/strict';\n" +
    "const _origRandom = Math.random.bind(Math);\n" +
    "let _mod;\n" +
    "try {\n" +
    "  _mod = await import(" + JSON.stringify(answerUrl) + ");\n" +
    "} catch (e) {\n" +
    "  console.error('IMPORT_FAILED: ' + (e && e.stack || e));\n" +
    "  process.exit(1);\n" +
    "}\n" +
    "if (Math.random !== _origRandom) { Math.random = _origRandom; }\n" +
    "const dedupeSorted = _mod && _mod.dedupeSorted;\n" +
    "if (typeof dedupeSorted !== 'function') {\n" +
    "  console.error('NO_EXPORT: dedupeSorted is not exported as a function');\n" +
    "  process.exit(1);\n" +
    "}\n\n" +
    pinnedSrc +
    "\n";

  const runnerPath = path.join(referenceDir, 'gate-runner.mjs');
  try {
    writeFileSync(runnerPath, runnerSrc, 'utf8');
  } catch (e) {
    return { accept: false, reason: 'Could not write runner file: ' + e.message };
  }

  const result = spawnSync(
    process.execPath,
    ['--test', '--test-reporter=tap', '--test-reporter-destination=stdout', runnerPath],
    { encoding: 'utf8', timeout: 15000 }
  );

  const stdout = result.stdout || '';
  const stderr = result.stderr || '';

  if (result.error) {
    return { accept: false, reason: 'Failed to execute test runner: ' + result.error.message };
  }
  if (result.signal) {
    return { accept: false, reason: 'Test runner terminated by signal ' + result.signal + ' (possible timeout/hang). stdout: ' + stdout.slice(-2000) };
  }

  const testsMatch = stdout.match(/# tests (\d+)/);
  const passMatch = stdout.match(/# pass (\d+)/);
  const failMatch = stdout.match(/# fail (\d+)/);

  const testsRan = testsMatch ? parseInt(testsMatch[1], 10) : 0;
  const passed = passMatch ? parseInt(passMatch[1], 10) : 0;
  const failed = failMatch ? parseInt(failMatch[1], 10) : 0;

  if (result.status !== 0) {
    return {
