      reason: 'Test process exited with status ' + result.status + '. tests=' + testsRan + ' pass=' + passed + ' fail=' + failed + '\n' + stdout.slice(-2000) + stderr.slice(-1000)
    };
  }

  if (testsRan !== expectedTestCount) {
    return {
      accept: false,
      reason: 'Expected ' + expectedTestCount + ' pinned tests to run but observed ' + testsRan + ' (possible early exit or tampering). stdout tail: ' + stdout.slice(-2000)
    };
  }

  if (failed !== 0 || passed !== expectedTestCount) {
    return {
      accept: false,
      reason: 'Not all pinned tests passed. tests=' + testsRan + ' pass=' + passed + ' fail=' + failed + '\n' + stdout.slice(-2000)
    };
  }

  return { accept: true, reason: 'All ' + expectedTestCount + ' pinned test cases passed (verified test count, pass count, fail count, and exit code).' };
}
